#!/bin/sh
# Regenerate all 230 composites of composites/table.csv with tools/glue.py and check their SHA-256.
# Run from the repository root:  sh composites/reproduce.sh [outdir]   (default composites/regenerated, git-ignored)
# Level-2 rows read the shipped level-1 composites composites/nNNN_jJ_COUNT.cert as B; each of those is
# byte-identical to the level-1 row it comes from, which the hash check below confirms.
