echo "regenerated 230 composites in $out"
"$PY" - "$out" <<'EOF'
import csv, hashlib, os, sys
out = sys.argv[1]
rows = list(csv.DictReader(open('composites/table.csv')))
bad = [r['id'] for r in rows if hashlib.sha256(open(os.path.join(out, r['id'] + '.cert'), 'rb').read()).hexdigest() != r['sha256']]
bad += [r['id'] for r in rows if r['file'] and open(r['file'], 'rb').read() != open(os.path.join(out, r['id'] + '.cert'), 'rb').read()]
print(f'{len(rows)} rows, {len(rows) - len(bad)} match composites/table.csv' + (', the shipped files included' if not bad else ''))
for b in bad: print('MISMATCH', b)
sys.exit(1 if bad or len(rows) != 230 else 0)
EOF
